        d.Add("Set_FaceSystem", ("Notices the computer", "Để ý cái máy"));
        d.Add("Set_FaceSystem_Desc", ("Sweats when the processor works hard, panics when the internet drops, cheers when the charger goes in.", "Đổ mồ hôi khi CPU chạy hết công suất, hoảng khi rớt mạng, sướng khi cắm sạc."));
        d.Add("Set_FaceStroll", ("Goes for a walk", "Đi dạo"));
        d.Add("Set_FaceStroll_Desc", ("Now and then, with nothing playing, it wanders along the empty taskbar and comes back.", "Lúc rảnh không có nhạc, thỉnh thoảng nó đi dạo dọc taskbar trống rồi quay về."));
        d.Add("Set_Face_GroupWear", ("Hats and glasses", "Mũ, kính, phụ kiện"));
        d.Add("Set_FaceHat", ("Hat", "Mũ"));
        d.Add("Set_FaceHat_Desc", ("Also on the face's right-click menu.", "Cũng chọn được khi chuột phải vào mặt."));
        d.Add("Set_FaceGlasses", ("Glasses", "Kính"));
