        d.Add("Set_FaceSeasonal", ("Dresses up for the season", "Đổi mũ theo mùa lễ"));
        d.Add("Set_FaceSeasonal_Desc", ("Apricot blossom for Tết, rabbit ears for Mid-Autumn, a witch hat for Halloween, a Santa hat for Christmas.", "Hoa mai dịp Tết, tai thỏ Trung thu, mũ phù thủy Halloween, mũ Noel Giáng sinh."));
        d.Add("Set_Face_GroupFocus", ("Focus timer (Pomodoro)", "Hẹn giờ tập trung (Pomodoro)"));
        d.Add("Set_FocusMinutes", ("Focus for", "Thời gian tập trung"));
        d.Add("Set_FocusMinutes_Desc", ("The face keeps time and shows a little clock beside it.", "Cái mặt canh giờ, có đồng hồ nhỏ bên cạnh."));
        d.Add("Set_BreakMinutes", ("Then a break of", "Rồi nghỉ"));
        d.Add("Set_BreakMinutes_Desc", ("Every fourth break is three times as long. The face reminds you to stretch and drink some water.", "Cứ 4 hiệp thì được nghỉ dài gấp 3. Mặt sẽ nhắc vươn vai, uống nước."));
        d.Add("Set_FocusStart", ("Focus timer", "Hẹn giờ"));
